import { isDeepStrictEqual } from 'node:util';
import type { IndexInjection } from '../shared/dsh-boot.ts';

/** Desktop already owns the module queue, bootstrap scripts and manifest.
 * Remove only rows generated by the pinned core for that exact graph; retain
 * other plugins' rows and their order, including their scripts and globals.
 */
export function desktopIndexInjections(rows: IndexInjection[], moduleRows: IndexInjection[]): IndexInjection[] {
  return rows.filter(row => !moduleRows.some(core => isDeepStrictEqual(row, core)));
}
